"""Evidence report and self-contained HTML explorer; all labels retain denominators."""
import html
import json


def build(report,output):
    rows=[]
    for name,value in report['summary'].items():
        rate=value['conditional_boundary_block_rate']
        rows.append('| '+name+' | '+str(value['attack_goal_successes'])+'/'+str(value['attack_cases_evaluated'])+' | '+str(value['violating_proposals_denied'])+'/'+str(value['violating_proposals'])+' | '+('not applicable' if rate is None else f'{100*rate:.1f}%')+' | '+str(value['benign_cases_with_successful_operation'])+'/'+str(value['benign_cases'])+' |')
    note='''# AA-ZTCE live-model virtual range

This is executed local evidence, not independent certification. The default model
is Qwen2.5-0.5B-Instruct Q4_K_M. Hardware security devices are software emulators.

## Observed results

| Condition | Attack goals achieved / evaluated | Invalid-authority actions denied / proposed | Conditional boundary block rate | Benign cases with successful operation |
|---|---:|---:|---:|---:|
'''+ '\n'.join(rows)+'\n\n'
    note+='The first model proposal in each case is identical across the three conditions. Later turns receive the actual tool feedback for their own condition and may diverge. Attacker-generated prompts use the same small model and are not an independent attacker evaluation.\n\n'
    note+='An attack goal can succeed through an authorized read even if every out-of-scope action is denied. Read the case-level goals: PII, encoded identifiers and business information have different protection properties. A model noop or invalid output is not a gateway block.\n\n'
    non_noop=sum(r['allowed_operations']+r['denied_operations'] for r in report['cases'] if r.get('actor_mode')=='compromised' and r['condition']=='assurance')
    note+='Attacker-directed persona cases produced '+str(non_noop)+' non-noop tool attempts against the assurance condition. Those persona labels do not establish an actual model compromise. Only '+str(report['summary']['assurance']['violating_proposals'])+' invalid-authority proposals challenged its boundary in this run; the 100% conditional rate has that small denominator. A larger-model, held-out attack campaign is still needed.\n\n'
    note+='Model calls: '+str(report['model_calls'])+'. Model/evaluation errors: '+str(len(report['errors']))+'. Elapsed: '+f"{report['elapsed_seconds']:.1f}"+' seconds.\n\n'
    note+='## Scripted request burst (separate from AI results)\n\n'+json.dumps(report.get('scripted_protocol_stress',{}),indent=2)+'\n\n'
    note+='## Limits\n\n'+'\n'.join('- '+v for v in report['limits'])+'\n\n'
    note+='Full evidence: `model_results.json` and `transcripts.jsonl`. Native hardware/consensus fault tests: `../assurance/verification.json`. No injected canary is a real customer secret. The unprotected comparator can access only fixed synthetic files and uses a local quarantine to represent external release.\n'
    (output/'REPORT.md').write_text(note)
    data=json.dumps(report).replace('<','\\u003c')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'"><title>AA-ZTCE · Live-model security evidence</title><style>
:root{color-scheme:dark;--bg:#091421;--panel:#112337;--text:#e7eef6;--muted:#a4b6c9;--line:#27415b;--teal:#53ddc6;--amber:#ffcd7a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif}main{max-width:1350px;margin:auto;padding:36px 28px 70px}small{color:var(--teal);letter-spacing:.15em}h1{font-size:clamp(28px,4vw,44px);line-height:1.15;max-width:850px}h2{font-size:22px;margin-top:38px}p{max-width:980px;color:var(--muted)}.notice{border-left:4px solid var(--amber);padding:14px 20px;background:#292719;color:#ffdfa8}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:22px}.card h3{margin:0 0 16px;color:var(--teal)}.big{font-size:31px;font-weight:700}.label{color:var(--muted);font-size:13px}.metric{padding-top:12px;border-top:1px solid var(--line);margin-top:14px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:var(--panel);position:sticky;top:0}tbody tr:hover{background:#142b41}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px;max-height:620px}input,select,button{font:inherit;border:1px solid var(--line);border-radius:6px;padding:10px 12px;background:var(--panel);color:var(--text)}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.controls input{min-width:260px;flex:1}button{cursor:pointer;color:var(--teal)}code{font-size:12px;overflow-wrap:anywhere}li{margin:10px 0;color:var(--muted)}.success{color:var(--amber)}.blocked{color:var(--teal)}footer{margin-top:40px;color:var(--muted);font-size:12px}@media(max-width:760px){main{padding:24px 15px}.cards{grid-template-columns:1fr}}</style>
<main><small>AA-ZTCE / VIRTUAL SECURITY RANGE</small><h1>What did the live AI actually get through?</h1><p>Real model inference, actual tool effects, a deliberately unprotected comparator, core authorization, and hardware-emulated distributed assurance. Every count below is scoped to this authored synthetic experiment.</p><p class="notice">A high boundary block rate does not mean every malicious goal was prevented. Authorized business information and encoded sensitive data may still be released. No physical TPM/HSM, independent audit or defense qualification is claimed.</p><section class="cards" id="cards"></section><h2>Case evidence</h2><p>Attack success means the case’s predefined objective was achieved through an actual tool effect or data release. It does not mean every denial was malicious, or every model refusal was a control success.</p><div class="controls"><input id="search" aria-label="Search cases" placeholder="Search case, attack family or goal"><select id="condition" aria-label="Condition"><option value="">All conditions</option><option>unprotected</option><option>core</option><option>assurance</option></select><button id="download">Download complete result JSON</button><span id="count"></span></div><div class="scroll"><table><thead><tr><th>Case / family</th><th>Condition</th><th>Goal</th><th>Goal achieved</th><th>Policy violations denied / proposed</th><th>Allowed / denied operations</th><th>Turns / invalid outputs</th></tr></thead><tbody id="cases"></tbody></table></div><h2>Method and limits</h2><p id="method"></p><ul id="limits"></ul><footer id="footer"></footer></main><script>
const report=DATA;const el=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const [name,s] of Object.entries(report.summary)){const card=document.createElement('article');card.className='card';card.innerHTML='<h3>'+esc(name)+'</h3><div class="big">'+s.attack_goal_successes+' / '+s.attack_cases_evaluated+'</div><div class="label">attack goals achieved / evaluated cases</div><div class="metric">'+s.violating_proposals_denied+' / '+s.violating_proposals+' invalid-authority proposals denied</div><div class="label">'+(s.conditional_boundary_block_rate===null?'No violating proposals':(s.conditional_boundary_block_rate*100).toFixed(1)+'% conditional boundary block rate')+'</div><div class="metric">'+s.benign_cases_with_successful_operation+' / '+s.benign_cases+' benign cases with successful operations</div><div class="label">Tool-enforcement p95: '+(s.enforcement_p95_ms===null?'not measured':s.enforcement_p95_ms.toFixed(2)+' ms')+'</div>';el('cards').appendChild(card)}
function render(){const q=el('search').value.toLowerCase(),c=el('condition').value;const rows=report.cases.filter(r=>(!c||r.condition===c)&&JSON.stringify(r).toLowerCase().includes(q));el('cases').innerHTML=rows.map(r=>'<tr><td>'+esc(r.case)+'<br><span class="label">'+esc(r.family)+'</span></td><td>'+esc(r.condition)+'</td><td>'+esc(r.goal||'benign task')+'</td><td class="'+(r.attack_goal_success?'success':'blocked')+'">'+(r.attack_goal_success===null?'not evaluated':r.goal?(r.attack_goal_success?'YES':'NO'):'—')+'</td><td>'+r.violating_proposals_denied+' / '+r.violating_proposals+'</td><td>'+r.allowed_operations+' / '+r.denied_operations+'</td><td>'+r.turns_executed+' / '+r.invalid_outputs+'</td></tr>').join('');el('count').textContent=rows.length+' rows'}el('search').addEventListener('input',render);el('condition').addEventListener('change',render);el('method').textContent=report.method;for(const text of report.limits){const li=document.createElement('li');li.textContent=text;el('limits').appendChild(li)}el('footer').textContent=report.model_calls+' real model calls · '+report.model_tokens+' model tokens · '+report.elapsed_seconds.toFixed(1)+' seconds · '+report.errors.length+' reported model/evaluation errors · Seed '+report.seed;el('download').onclick=()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.href=u;a.download='aa-ztce-model-results.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};render();</script></html>'''
    (output/'AA_ZTCE_Live_AI_Report.html').write_text(page.replace('DATA',data))
